package com.postiepete;

import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Follows a Chambers of Xeric raid, Challenge Mode included: each room's and level's time, the Great Olm's,
 * and the raid's points, so they can be sent with the reward chest's loot, which is opened some time later.
 * <p>
 * The game tells the party the time since the raid began at the end of each level, and the raid's time on its
 * completion, so each part's own time is the difference from the one before.
 */
class ChambersOfXeric
{
	/**
	 * Sent to the raid's party when the raid starts.
	 */
	static final String RAID_START_MESSAGE = "The raid has begun!";

	/**
	 * Sent to the raid's party when the raid is completed.
	 */
	static final String RAID_COMPLETE_MESSAGE = "Congratulations - your raid is complete!";

	// "Upper level complete! Duration: 7:01", tags removed, sent to the raid's party: the time since the raid
	// began. The CoX timers hub plugin reads the same message, adding the level's own time to it.
	static final Pattern LEVEL_COMPLETE_PATTERN = Pattern.compile(
		"(?<level>\\w+) level complete! Duration: (?<time>[0-9:]+(?:\\.[0-9]+)?)");

	// The raid's time in its completion message, tags removed: "...Team size: 3 players Duration: 21:30 Personal
	// best: 20:00" or "... Duration: 19:45 (new personal best)". Same as RuneLite's chat commands plugin reads.
	// The groups are the ones PostiePetePlugin.parseKillTime reads.
	static final Pattern COMPLETION_TIME_PATTERN = Pattern.compile(
		"Duration: (?<time>[0-9:]+(?:\\.[0-9]+)?)(?:(?<newpb> \\(new personal best\\))"
			+ "|\\.? ?Personal best: (?<pb>[0-9:]+(?:\\.[0-9]+)?))?");

	/**
	 * The split after the last level: the time from its end to the raid's completion.
	 */
	static final String OLM = "Great Olm";

	private final RaidSplits splits = new RaidSplits();

	// The raid's time at the end of the last level, 0 at the start. Null when unknown: the raid's start wasn't
	// seen (e.g. the plugin was turned on mid-raid), so a level's own time can't be worked out.
	private Double lastLevelEnd;
	private boolean levelSeen;
	private LootEvent.Points points;

	// The raid timer's ticks when the next room's time started: at the raid's or the level's start, or the last
	// room's completion. Null when unknown.
	private Integer roomStartTicks;

	/**
	 * The raid's time and personal best in its completion message, tags removed, or null if it shows none.
	 */
	static LootEvent.KillTime completionTime(String message)
	{
		Matcher matcher = COMPLETION_TIME_PATTERN.matcher(message);
		return matcher.find() ? PostiePetePlugin.parseKillTime(matcher) : null;
	}

	void onRaidStarted()
	{
		splits.onRunStarted();
		lastLevelEnd = 0.0;
		levelSeen = false;
		roomStartTicks = 0;
	}

	/**
	 * Called when a room is completed, with the raid timer's ticks at that time. Added to the splits in the order
	 * completed, before its level's. The room's time runs from the last room's completion or the level's start, so
	 * it includes getting to the room.
	 */
	void onRoomCompleted(String room, int raidTicks)
	{
		if (roomStartTicks != null && raidTicks >= roomStartTicks)
		{
			splits.onBossCompleted(room, (raidTicks - roomStartTicks) * 6 / 10.0);
		}
		roomStartTicks = raidTicks;
	}

	/**
	 * Called on a level's completion message, with the level as the game names it (e.g. "Upper"), the time since
	 * the raid began in seconds as the message shows it, and the raid timer's ticks.
	 */
	void onLevelCompleted(String level, double raidTime, int raidTicks)
	{
		if (lastLevelEnd != null && raidTime >= lastLevelEnd)
		{
			splits.onBossCompleted(level + " level", raidTime - lastLevelEnd);
		}
		lastLevelEnd = raidTime;
		levelSeen = true;
		roomStartTicks = raidTicks;
	}

	/**
	 * Called on the raid's completion message, with the raid's time in seconds if it showed one, and the party's
	 * and the player's points.
	 */
	void onRaidCompleted(Double raidTime, int totalPoints, int personalPoints)
	{
		if (raidTime != null && levelSeen && lastLevelEnd != null && raidTime >= lastLevelEnd)
		{
			splits.onBossCompleted(OLM, raidTime - lastLevelEnd);
		}
		splits.onRaidCompleted();
		points = totalPoints > 0 ? new LootEvent.Points(totalPoints, personalPoints) : null;
		lastLevelEnd = null;
		levelSeen = false;
		roomStartTicks = null;
	}

	/**
	 * The completed raid's splits, or the raid so far if its completion was missed. Consumed.
	 */
	List<LootEvent.Split> consumeSplits()
	{
		return splits.consumeSplits();
	}

	/**
	 * The completed raid's points, or null if its completion wasn't seen. Consumed.
	 */
	LootEvent.Points consumePoints()
	{
		LootEvent.Points result = points;
		points = null;
		return result;
	}

	void reset()
	{
		splits.reset();
		lastLevelEnd = null;
		levelSeen = false;
		points = null;
		roomStartTicks = null;
	}
}

package com.postiepete;

/**
 * A new item added to the collection log.
 */
class CollectionLogEvent extends PostieEvent
{
	/**
	 * Item name from the game's item data, e.g. "Abyssal whip". Not unique: several collection
	 * log items can share a name (e.g. the chompy bird hats), use itemId to tell them apart.
	 */
	final String itemName;

	/**
	 * Exact item ID of the new collection log item.
	 */
	final int itemId;

	CollectionLogEvent(Common common, String itemName, int itemId)
	{
		super(COLLECTION_LOG, common);
		this.itemName = itemName;
		this.itemId = itemId;
	}
}

package com.postiepete;

/**
 * A completed combat task.
 */
class CombatAchievementEvent extends PostieEvent
{
	/**
	 * easy, medium, hard, elite, master or grandmaster.
	 */
	final String tier;

	/**
	 * Task name, e.g. "Noxious Foe".
	 */
	final String task;

	/**
	 * The game's task ID, e.g. 648. Null if the game's message
	 * didn't include it.
	 */
	final Integer taskId;

	CombatAchievementEvent(Common common, String tier, String task, Integer taskId)
	{
		super(COMBAT_ACHIEVEMENT, common);
		this.tier = tier;
		this.task = task;
		this.taskId = taskId;
	}
}

package com.postiepete;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;

/**
 * Finds when each Chambers of Xeric room is completed. The game doesn't say, so like the CoX Timers hub plugin, each
 * room's blocking obstacle (the crystal or barrier that opens when the room is done) is followed until it stops
 * blocking its tile.
 * <p>
 * The room layout and obstacles come from dey0's CoX Timers plugin (BSD 2-Clause License, Copyright (c) 2021,
 * dey0).
 */
class CoxRooms
{
	// A raid's map is built from template chunks: pp_xxxxxxxxxx_yyyyyyyyyyy_rr0 (plane, chunk x, chunk y, rotation).
	// Each room takes 4x4 chunks, so the low two bits of x and y, and the rotation, don't matter.
	private static final int ROOM_MASK = 0b11_1111111100_11111111100_00_0;

	private static final Map<Integer, String> ROOMS = new HashMap<>();

	static
	{
		// The room's plane and chunk y in the template, from the upper floor's rooms to the lower's. Each room comes
		// in three versions, at chunk x 102 to 104: the path turning one way, going through, or turning the other.
		room(0, 164, "Shamans");
		room(0, 165, "Vasa");
		room(0, 166, "Vanguards");
		room(0, 167, "Ice demon");
		room(0, 168, "Thieving");
		room(1, 164, "Mystics");
		room(1, 165, "Tekton");
		room(1, 166, "Muttadiles");
		room(1, 167, "Tightrope");
		room(2, 164, "Guardians");
		room(2, 165, "Vespula");
		room(2, 167, "Crabs");
	}

	/**
	 * The objects that block a room until it is completed.
	 */
	private static final Set<Integer> OBSTACLES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ObjectID.INVISIBLE_TYPE8_BLOCKING, // Shamans, Thieving, Guardians
		ObjectID.RAIDS_SKELETALMYSTICS_SYMBOL,
		ObjectID.RAIDS_TIGHTROPE_BARRIER,
		ObjectID.RAIDS_LASERCRABS_BIGCRYSTAL_1,
		ObjectID.RAIDS_LASERCRABS_BIGCRYSTAL_2,
		ObjectID.RAIDS_LASERCRABS_BIGCRYSTAL_3,
		ObjectID.RAIDS_LASERCRABS_BIGCRYSTAL_4,
		ObjectID.RAIDS_LASERCRABS_BIGCRYSTAL_5,
		ObjectID.RAIDS_ICEDEMON_SNOW,
		ObjectID.RAIDS_BLOCKAGE_PURPLE_SMALL, // Vasa
		ObjectID.RAIDS_BLOCKAGE_ORANGE, // Tekton, Vanguards
		ObjectID.RAIDS_BLOCKAGE_GREEN, // Muttadiles
		ObjectID.RAIDS_VESPULA_BOIL_BLOCKING)));

	// Each room's obstacle that is still blocking, by room name
	private final Map<String, WorldPoint> obstacles = new LinkedHashMap<>();

	private static void room(int plane, int chunkY, String name)
	{
		for (int chunkX = 102; chunkX <= 104; chunkX++)
		{
			ROOMS.put(plane << 24 | chunkX << 16 | chunkY << 5, name);
		}
	}

	/**
	 * The room a raid map template chunk is part of, or null if it isn't a room with an obstacle.
	 */
	static String roomName(int templateChunk)
	{
		return ROOMS.get(templateChunk & ROOM_MASK);
	}

	static boolean isObstacle(int objectId)
	{
		return OBSTACLES.contains(objectId);
	}

	/**
	 * Called when a room's obstacle spawns, with where it is.
	 */
	void onObstacleSpawned(String room, WorldPoint location)
	{
		obstacles.put(room, location);
	}

	/**
	 * The rooms whose obstacle is still blocking, and where it is. The caller removes a room once it is completed
	 * or its obstacle is out of view.
	 */
	Map<String, WorldPoint> obstacles()
	{
		return obstacles;
	}

	void reset()
	{
		obstacles.clear();
	}
}

package com.postiepete;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.util.Text;

/**
 * The tick of the player's first landed hit on each boss, for bosses the game prints no kill time for (e.g. the
 * God Wars Dungeon generals, the Dagannoth Kings, Barrows). Keyed by the name the kill count message uses, so a
 * kill can look up when its fight started. Each kill takes its start, so a respawned boss starts again from the
 * next first hit.
 */
class FightStarts
{
	/**
	 * A fight with no hit for this long is over, e.g. the player left, so the next hit starts a new one.
	 */
	static final int STALE_TICKS = 200;

	/**
	 * Barrows brothers are fought one at a time, with walking and digging in between, and the chest is
	 * opened after the last one, so a run's start is kept for longer.
	 */
	static final int BARROWS_STALE_TICKS = 1500;

	static final String BARROWS = "barrows chest";
	static final String KRAKEN = "kraken";
	static final String ROYAL_TITANS = "royal titans";
	static final String HUEYCOATL = "hueycoatl";

	private static final Set<Integer> BARROWS_BROTHERS = Set.of(
		NpcID.BARROWS_AHRIM, NpcID.BARROWS_DHAROK, NpcID.BARROWS_GUTHAN,
		NpcID.BARROWS_KARIL, NpcID.BARROWS_TORAG, NpcID.BARROWS_VERAC);

	// The Kraken is disturbed and fought along with its tentacles, which have other names
	private static final Set<Integer> KRAKEN_PARTS = Set.of(
		NpcID.SLAYER_KRAKEN_BOSS, NpcID.SLAYER_KRAKEN_BOSS_WHIRLPOOL,
		NpcID.SLAYER_KRAKEN_BOSS_TENTACLE, NpcID.SLAYER_KRAKEN_BOSS_TENTACLE_WHIRLPOOL);

	// The two Royal Titans are named after themselves, not the kill count message
	private static final Set<Integer> ROYAL_TITANS_PARTS = Set.of(
		NpcID.RT_FIRE_QUEEN, NpcID.RT_FIRE_QUEEN_INACTIVE, NpcID.RT_ICE_KING, NpcID.RT_ICE_KING_INACTIVE);

	// The Hueycoatl is fought at its head, tail and body parts
	private static final Set<Integer> HUEYCOATL_PARTS = Set.of(
		NpcID.HUEY_HEAD, NpcID.HUEY_HEAD_INVULNERABLE, NpcID.HUEY_HEAD_ENRAGED,
		NpcID.HUEY_TAIL, NpcID.HUEY_TAIL_BROKEN, NpcID.HUEY_BODY_PART, NpcID.HUEY_BODY_PART_BROKEN);

	private final Map<String, Fight> fights = new HashMap<>();

	/**
	 * The kill count message name, in lower case, that hits on the NPC count towards. Every Barrows brother
	 * counts towards the "Barrows chest", the Kraken's tentacles towards the Kraken, and the parts of the Royal
	 * Titans and the Hueycoatl towards them. Other NPCs use their own name, which is what their kill count
	 * message calls them (bosses with several forms keep one name).
	 */
	static String key(int npcId, String npcName)
	{
		if (BARROWS_BROTHERS.contains(npcId))
		{
			return BARROWS;
		}
		if (KRAKEN_PARTS.contains(npcId))
		{
			return KRAKEN;
		}
		if (ROYAL_TITANS_PARTS.contains(npcId))
		{
			return ROYAL_TITANS;
		}
		if (HUEYCOATL_PARTS.contains(npcId))
		{
			return HUEYCOATL;
		}
		return npcName != null ? Text.removeTags(npcName).toLowerCase() : null;
	}

	/**
	 * Called on each of the player's own hitsplats on an NPC, with the NPC's {@link #key}.
	 */
	void onHit(String key, int tick)
	{
		if (key == null)
		{
			return;
		}
		Fight fight = fights.get(key);
		if (fight == null || isStale(key, fight, tick))
		{
			fight = new Fight(tick);
			fights.put(key, fight);
		}
		fight.lastHitTick = tick;
	}

	/**
	 * The tick of the first hit of the fight for the kill count message's name, or null if there is no recent
	 * one. Consumed, so the next kill of the same boss starts from its own first hit.
	 */
	Integer take(String killName, int tick)
	{
		if (killName == null)
		{
			return null;
		}
		String key = killName.toLowerCase();
		Fight fight = fights.remove(key);
		return fight != null && !isStale(key, fight, tick) ? fight.firstHitTick : null;
	}

	/**
	 * The fight with the most recent hit that isn't over, or null if there is none.
	 */
	Current current(int tick)
	{
		Map.Entry<String, Fight> latest = null;
		for (Map.Entry<String, Fight> entry : fights.entrySet())
		{
			if (!isStale(entry.getKey(), entry.getValue(), tick)
				&& (latest == null || entry.getValue().lastHitTick > latest.getValue().lastHitTick))
			{
				latest = entry;
			}
		}
		return latest != null ? new Current(latest.getKey(), latest.getValue().firstHitTick) : null;
	}

	/**
	 * Drops fights that are over, e.g. ones on NPCs that aren't bosses.
	 */
	void prune(int tick)
	{
		fights.entrySet().removeIf(entry -> isStale(entry.getKey(), entry.getValue(), tick));
	}

	void reset()
	{
		fights.clear();
	}

	private static boolean isStale(String key, Fight fight, int tick)
	{
		int staleTicks = BARROWS.equals(key) ? BARROWS_STALE_TICKS : STALE_TICKS;
		return tick - fight.lastHitTick > staleTicks;
	}

	@Value
	static class Current
	{
		/**
		 * The fight's {@link #key}.
		 */
		String key;
		int firstHitTick;
	}

	private static class Fight
	{
		final int firstHitTick;
		int lastHitTick;

		Fight(int firstHitTick)
		{
			this.firstHitTick = firstHitTick;
			this.lastHitTick = firstHitTick;
		}
	}
}

package com.postiepete;

/**
 * The Fractured Archive's messages. Its run is followed with {@link RaidSplits}: each boss's duration, where the
 * path (the boss picked at each of the three choices) is the 2nd to 4th boss.
 */
final class FracturedArchive
{
	/**
	 * The Loot Tracker's name for the raid's reward chest.
	 */
	static final String LOOT_SOURCE = "Fractured Archive";

	/**
	 * Start of the kill count message sent when the raid is completed, before the chest is opened.
	 */
	static final String COMPLETION_MESSAGE = "Your completed Fractured Archive count is";

	/**
	 * Sent when the first boss starts, at the start of every run.
	 */
	static final String RUN_START_MESSAGE = "Challenge started: Archive Guardian.";

	private FracturedArchive()
	{
	}
}

package com.postiepete;

import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Remembers the game's last kill count message, e.g. "Your TzKal-Zuk kill count is: 12." or "Your completed
 * Theatre of Blood: Hard Mode count is: 40.", so the loot that follows can say which kill it came from. The
 * Loot Tracker only knows the loot's own name (the NPC that dropped it, or the chest), which isn't always the
 * boss: raid chests are named without their mode, and some bosses' loot comes from another NPC.
 */
class KillCounts
{
	// RuneLite's chat commands plugin's kill count pattern, on the message with its colour tags. Covers kills
	// ("kill count"), raids ("Your completed ... count"), Wintertodt ("subdued"), the Gauntlet ("completion
	// count") and chests ("Barrows chest count"). The red count is what tells these apart from other "is:" messages.
	static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	// Raids say "Your completed <raid> count"; their kill count only goes with the reward chest
	private static final String RAID_PREFIX = "completed ";

	// Kills the game reports no loot for at the kill, so without this they would never be sent: the Fight Caves
	// and the Inferno give their cape and Tokkul as a reward, and Wintertodt and Tempoross rewards are claimed
	// separately (their reward loot isn't one per kill). Only these get a kill without loot: other kill count
	// messages (agility laps, the Sepulchre, activities whose chest is opened later) would be noise or counted twice.
	static final Set<String> KILLS_WITHOUT_LOOT = Set.of("TzKal-Zuk", "TzTok-Jad", "Wintertodt", "Tempoross");

	private final int npcMaxAgeTicks;
	private final int chestMaxAgeTicks;
	private final int withoutLootTicks;

	private LootEvent.Kill last;
	private boolean lastIsRaid;
	private int lastTick;

	/**
	 * @param npcMaxAgeTicks   how long after the message NPC loot can still claim it
	 * @param chestMaxAgeTicks how long after the message a reward chest can still claim it (chests are opened later)
	 * @param withoutLootTicks how long after the message a kill in {@link #KILLS_WITHOUT_LOOT} waits for loot
	 *                         before it counts as a kill without loot; loot comes on the message's own tick
	 */
	KillCounts(int npcMaxAgeTicks, int chestMaxAgeTicks, int withoutLootTicks)
	{
		this.npcMaxAgeTicks = npcMaxAgeTicks;
		this.chestMaxAgeTicks = chestMaxAgeTicks;
		this.withoutLootTicks = withoutLootTicks;
	}

	/**
	 * Remembers the kill count if the message is one, replacing any earlier one. Returns it, or null.
	 *
	 * @param message the chat message as the game sent it, with its colour tags
	 */
	LootEvent.Kill onMessage(String message, int tick)
	{
		Matcher matcher = KILL_COUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		String name = Text.removeTags(matcher.group("boss")).trim();
		int count;
		try
		{
			count = Integer.parseInt(matcher.group("kc").replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return null;
		}

		last = new LootEvent.Kill(name, count);
		lastIsRaid = RAID_PREFIX.equals(matcher.group("pre"));
		lastTick = tick;
		return last;
	}

	/**
	 * The kill count for NPC loot: the last message if it is recent and not a raid's, which belongs to the chest.
	 * Consumed, so it can't be attached to a later kill.
	 */
	LootEvent.Kill claimForNpcLoot(int tick)
	{
		if (last == null || lastIsRaid || tick - lastTick > npcMaxAgeTicks)
		{
			return null;
		}
		return consume();
	}

	/**
	 * The kill count for a reward chest: the last message if it is recent enough and names the chest, e.g. the
	 * "Theatre of Blood" chest after "Theatre of Blood: Hard Mode", or the "Barrows" chest after "Barrows chest".
	 * Consumed, so it can't be attached to a later chest.
	 */
	LootEvent.Kill claimForChest(String chestName, int tick)
	{
		if (last == null || chestName == null || tick - lastTick > chestMaxAgeTicks
			|| !last.getName().toLowerCase().startsWith(chestName.toLowerCase()))
		{
			return null;
		}
		return consume();
	}

	/**
	 * A kill in {@link #KILLS_WITHOUT_LOOT} that no loot claimed in time, to be sent as a kill without loot.
	 * Consumed, so it is sent once. Call every tick.
	 */
	LootEvent.Kill takeKillWithoutLoot(int tick)
	{
		if (last == null || lastIsRaid || tick - lastTick <= withoutLootTicks
			|| !KILLS_WITHOUT_LOOT.contains(last.getName()))
		{
			return null;
		}
		return consume();
	}

	void reset()
	{
		last = null;
	}

	private LootEvent.Kill consume()
	{
		LootEvent.Kill kill = last;
		last = null;
		return kill;
	}
}

package com.postiepete;

import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Value;
import lombok.With;

/**
 * Loot from an NPC kill, a raid or reward chest, a clue casket etc.
 */
class LootEvent extends PostieEvent
{
	/**
	 * What the loot came from and how the kill went: its name, kill count, kill time, personal best and splits.
	 */
	final Source source;
	final List<Drop> drops;

	/**
	 * The player's items when the fight started, for boss kills. Null for other loot, or when sending gear is
	 * turned off.
	 */
	final PlayerItems playerItems;

	/**
	 * How many players were in the fight, for boss kills. Null for other loot and skilling bosses.
	 */
	final Team team;

	LootEvent(Common common, Source source, List<Drop> drops, PlayerItems playerItems, Team team)
	{
		super(LOOT, common);
		this.source = source;
		this.drops = drops;
		this.playerItems = playerItems;
		this.team = team;
	}

	@Value
	static class Source
	{
		/**
		 * The boss, raid or activity: the kill count message's name when one came with the loot (e.g. "Theatre of
		 * Blood: Hard Mode", "Leviathan", "Barrows chest"), otherwise the Loot Tracker's name (e.g. "Vorkath",
		 * "Reward cart (Wintertodt)", "Clue Scroll (Hard)").
		 */
		String name;

		/**
		 * The Loot Tracker's name when it differs from name, e.g. "Theatre of Blood" for every raid mode, or
		 * "The Leviathan" for "Leviathan". Null when they are the same, or when name already is the Loot
		 * Tracker's name (no kill count message came with the loot).
		 */
		String lootName;

		/**
		 * The NPC's ID for kills (e.g. 8061 for Vorkath), or null for non-NPC sources.
		 */
		Integer npcId;

		/**
		 * The kill count after this kill, from the kill count message. Null when no kill count message came
		 * with the loot; name is then the Loot Tracker's name.
		 */
		Integer killCount;

		/**
		 * Kill / completion duration in seconds (e.g. 83.4): the game's, or for bosses it prints none for, the
		 * plugin's own time from the first hit. Null if neither is known.
		 */
		Double duration;

		/**
		 * The personal best in seconds as the game reported it with the duration: the duration itself for a new
		 * personal best, otherwise the "Personal best:" time. Null when the game didn't report one.
		 */
		Double personalBest;

		/**
		 * True when the game's kill time message said "(new personal best)", false otherwise. A time that ties the
		 * personal best is not a new one.
		 */
		boolean newPersonalBest;

		/**
		 * How far the run got when the loot was claimed, for activities where loot can be claimed early: the
		 * Fortis Colosseum wave (1-12) or the Doom of Mokhaiotl delve level. Null otherwise.
		 */
		Integer wave;

		/**
		 * The run's parts in the order played, for the Fortis Colosseum, Doom of Mokhaiotl, the Fight Caves, the
		 * Inferno, the Chambers of Xeric, the Theatre of Blood, the Tombs of Amascut and the Fractured Archive. Null
		 * for all other loot, and when none were seen (e.g. the plugin was turned on mid-run).
		 */
		List<Split> splits;

		/**
		 * The raid's points, for the Chambers of Xeric and the Tombs of Amascut. Null for all other loot, and when
		 * the raid's completion wasn't seen.
		 */
		@With
		Points points;

		/**
		 * The raid's invocation level, for the Tombs of Amascut, e.g. 300. Null for all other loot, and when the
		 * raid's completion wasn't seen.
		 */
		@With
		Integer invocation;

		/**
		 * Builds the source from the Loot Tracker's name and the kill count message that came with the loot, if
		 * any. Empty splits are sent as null.
		 */
		static Source of(String lootTrackerName, Kill kill, Integer npcId, KillTime killTime, Integer wave,
			List<Split> splits)
		{
			String name = kill != null ? kill.getName() : lootTrackerName;
			String lootName = lootTrackerName != null && !lootTrackerName.equals(name) ? lootTrackerName : null;
			return new Source(name, lootName, npcId, kill != null ? kill.getCount() : null,
				killTime != null ? killTime.getDuration() : null,
				killTime != null ? killTime.getPersonalBest() : null,
				killTime != null && killTime.isNewPersonalBest(),
				wave,
				splits != null && !splits.isEmpty() ? splits : null,
				null,
				null);
		}
	}

	/**
	 * A kill count message: the boss or raid as it names it and the count. Sent as the source's name and killCount.
	 */
	@Value
	static class Kill
	{
		/**
		 * The boss or raid as the kill count message names it, e.g. "TzKal-Zuk", "Theatre of Blood: Hard Mode",
		 * "Chambers of Xeric Challenge Mode", "Wintertodt" or "Barrows chest".
		 */
		String name;

		/**
		 * The kill count after this kill, e.g. 40.
		 */
		int count;
	}

	/**
	 * A kill or completion time message: the duration, the personal best it reported and whether it was a new one.
	 */
	@Value
	static class KillTime
	{
		double duration;

		/**
		 * The duration for a new personal best, the "Personal best:" time otherwise, or null if neither was shown.
		 */
		Double personalBest;

		/**
		 * True when the message said "(new personal best)".
		 */
		boolean newPersonalBest;
	}

	@Value
	static class Split
	{
		/**
		 * The part of the run: "Wave 3" (Colosseum, Fight Caves, Inferno), "Level 22" (Doom delve level), "Tekton",
		 * "Upper level" or "Great Olm" (Chambers of Xeric, each level after its rooms), or the room or boss as the
		 * game writes it in its completion message, e.g. "Xarpus" (Theatre of Blood), "Path of Het" or "Akkha" (Tombs
		 * of Amascut) or "Bork" (Fractured Archive).
		 */
		String name;

		/**
		 * The part's duration in seconds, e.g. 141.0. What it covers depends on the content: see the README.
		 */
		double duration;
	}

	/**
	 * A Chambers of Xeric or Tombs of Amascut raid's points when it was completed, which set the chance of a unique.
	 */
	@Value
	static class Points
	{
		/**
		 * The whole party's points. Null for the Tombs of Amascut, whose total the game doesn't send.
		 */
		Integer total;

		/**
		 * The sender's own points.
		 */
		int personal;
	}

	@Value
	@AllArgsConstructor
	static class Team
	{
		/**
		 * Players in the team, including the sender (1 = solo). For raids, the game's party size. For other
		 * bosses, the sender plus every other player who was near them at some point during the fight.
		 */
		int size;

		/**
		 * The players the Chambers of Xeric party added to the raid's scale with its scaling setting, read when the
		 * raid was completed: the raid scales as size + scaling players (e.g. 2 players at scaling 3 = a 5-player
		 * raid). Null for all other content.
		 */
		Integer scaling;

		Team(int size)
		{
			this(size, null);
		}
	}

	@Value
	static class Drop
	{
		int itemId;

		/**
		 * Item name from the game's item data, e.g. "Dragon bones". Not unique, use itemId as the key.
		 */
		String itemName;
		int quantity;

		/**
		 * GE value of one item at the time of the drop, from the OSRS Wiki real-time prices
		 * that RuneLite loads. Untradeable variants RuneLite knows about (e.g. Sanguine Torva) are
		 * valued as their tradeable item. 0 for other untradeable items, or if prices haven't loaded.
		 */
		long value;
	}
}

package com.postiepete;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * When other players were near the player, by game tick, so a kill can count how many were in the fight with
 * them. Each player's nearby time is kept as tick ranges. Names are only kept here, to count each player once;
 * they are never sent.
 */
class NearbyPlayers
{
	/**
	 * How close another player must be, in tiles, to count as near.
	 */
	static final int RADIUS_TILES = 15;

	/**
	 * How long ranges are kept after they end: longer than any fight that is counted.
	 */
	static final int MAX_AGE_TICKS = 3000;

	private final Map<String, List<Range>> seen = new HashMap<>();

	/**
	 * Called each tick another player is near. A tick right after their last one extends that range.
	 */
	void onNear(String player, int tick)
	{
		if (player == null)
		{
			return;
		}
		List<Range> ranges = seen.computeIfAbsent(player, name -> new ArrayList<>());
		Range last = ranges.isEmpty() ? null : ranges.get(ranges.size() - 1);
		if (last != null && tick - last.toTick <= 1)
		{
			last.toTick = Math.max(last.toTick, tick);
		}
		else
		{
			ranges.add(new Range(tick));
		}
	}

	/**
	 * How many other players were near at some point between the two ticks.
	 */
	int count(int fromTick, int toTick)
	{
		int count = 0;
		for (List<Range> ranges : seen.values())
		{
			for (Range range : ranges)
			{
				if (range.fromTick <= toTick && range.toTick >= fromTick)
				{
					count++;
					break;
				}
			}
		}
		return count;
	}

	/**
	 * Drops ranges that ended more than {@link #MAX_AGE_TICKS} ago.
	 */
	void prune(int tick)
	{
		seen.values().forEach(ranges -> ranges.removeIf(range -> tick - range.toTick > MAX_AGE_TICKS));
		seen.values().removeIf(List::isEmpty);
	}

	void reset()
	{
		seen.clear();
	}

	private static class Range
	{
		final int fromTick;
		int toTick;

		Range(int tick)
		{
			this.fromTick = tick;
			this.toTick = tick;
		}
	}
}

package com.postiepete;

import java.util.List;
