/**
 * The player's equipment, inventory, rune pouch and quiver at the start of a trip.
 */
@Value
class PlayerItems
{
	/**
	 * Keyed by equipment slot name (e.g. "WEAPON", "AMMO"). Empty slots are omitted.
	 */
	Map<String, SlotItem> equipment;

	/**
	 * Keyed by inventory slot index ("0" - "27"). Empty slots are omitted.
	 */
	Map<String, SlotItem> inventory;

	/**
	 * Runes in the rune pouch, or null if empty. Empty pouch slots are omitted.
	 * Sent unconditionally: the game keeps this value even when no pouch is carried,
	 * so the receiver should check the inventory to decide whether it is in use.
	 */
	List<SlotItem> runePouch;

	/**
	 * Contents of the extra ammo slot (Dizana's quiver / bolt pouch), or null if empty.
	 * Sent unconditionally: the game keeps this value even when no quiver is worn,
	 * so the receiver should check the equipped cape to decide whether it is in use.
	 */
	SlotItem quiver;

	@Value
	static class SlotItem
	{
		int id;
		int quantity;
	}
}

package com.postiepete;

import lombok.Value;

/**
 * Fields shared by every event sent to the API. Each event type adds its own fields in a
 * subclass, so a payload only contains the fields that apply to its type.
 */
abstract class PostieEvent
{
	static final String LOOT = "loot";
	static final String COLLECTION_LOG = "collection_log";
	static final String COMBAT_ACHIEVEMENT = "combat_achievement";

	/**
	 * "loot", "collection_log" or "combat_achievement".
	 */
	final String eventType;
	final String timestamp;
	final String rsn;

	/**
	 * RuneLite account hash: stable per account, unaffected by name changes. Sent as a
	 * string because it is a 64-bit value that JavaScript numbers can't represent exactly.
	 */
	final String accountHash;

	PostieEvent(String eventType, Common common)
	{
		this.eventType = eventType;
		this.timestamp = common.timestamp;
		this.rsn = common.rsn;
		this.accountHash = common.accountHash;
	}

	/**
	 * The shared fields, captured once when an event happens and passed to the event's constructor.
	 */
	@Value
	static class Common
	{
		String timestamp;
		String rsn;
		String accountHash;
	}
}

