package com.postiepete;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;

public class FightStartsTest
{
	private static final int GRAARDOR_ID = 2215;

	@Test
	public void killTakesTheFirstHitOfItsFight()
	{
		FightStarts starts = new FightStarts();
		String key = FightStarts.key(GRAARDOR_ID, "General Graardor");
		starts.onHit(key, 100);
		starts.onHit(key, 105);
		starts.onHit(key, 140);

		assertEquals(Integer.valueOf(100), starts.take("General Graardor", 141));
	}

	@Test
	public void eachRespawnStartsFromItsOwnFirstHit()
	{
		FightStarts starts = new FightStarts();
		String key = FightStarts.key(GRAARDOR_ID, "General Graardor");
		starts.onHit(key, 100);
		assertEquals(Integer.valueOf(100), starts.take("General Graardor", 140));

		starts.onHit(key, 190);
		starts.onHit(key, 220);
		assertEquals(Integer.valueOf(190), starts.take("General Graardor", 221));
		assertNull(starts.take("General Graardor", 222));
	}

	@Test
	public void killCountNamesMatchNpcNamesInAnyCase()
	{
		FightStarts starts = new FightStarts();
		starts.onHit(FightStarts.key(499, "Thermonuclear smoke devil"), 100);

		assertEquals(Integer.valueOf(100), starts.take("Thermonuclear Smoke Devil", 150));
	}

	@Test
	public void barrowsStartsOnTheFirstBrother()
	{
		FightStarts starts = new FightStarts();
		starts.onHit(FightStarts.key(NpcID.BARROWS_AHRIM, "Ahrim the Blighted"), 100);
		// Walking and digging to the next brothers
		starts.onHit(FightStarts.key(NpcID.BARROWS_DHAROK, "Dharok the Wretched"), 700);
		starts.onHit(FightStarts.key(NpcID.BARROWS_VERAC, "Verac the Defiled"), 1500);

		// The chest is opened a while after the last brother
		assertEquals(Integer.valueOf(100), starts.take("Barrows chest", 2000));
	}

	@Test
	public void krakenTentaclesCountTowardsTheKraken()
	{
		FightStarts starts = new FightStarts();
		starts.onHit(FightStarts.key(NpcID.SLAYER_KRAKEN_BOSS_TENTACLE, "Enormous Tentacle"), 100);
		starts.onHit(FightStarts.key(NpcID.SLAYER_KRAKEN_BOSS, "Kraken"), 130);

		assertEquals(Integer.valueOf(100), starts.take("Kraken", 160));
	}

	@Test
	public void bossPartsCountTowardsTheirBoss()
	{
		assertEquals("royal titans", FightStarts.key(NpcID.RT_FIRE_QUEEN, "Branda the Fire Queen"));
		assertEquals("royal titans", FightStarts.key(NpcID.RT_ICE_KING, "Eldric the Ice King"));
		assertEquals("hueycoatl", FightStarts.key(NpcID.HUEY_TAIL, "Hueycoatl tail"));
		assertEquals("hueycoatl", FightStarts.key(NpcID.HUEY_BODY_PART, "Hueycoatl body"));
	}

	@Test
	public void aHitAfterALongBreakStartsANewFight()
	{
		FightStarts starts = new FightStarts();
		String key = FightStarts.key(GRAARDOR_ID, "General Graardor");
		starts.onHit(key, 100);
		starts.onHit(key, 100 + FightStarts.STALE_TICKS + 1);

		assertEquals(Integer.valueOf(100 + FightStarts.STALE_TICKS + 1), starts.take("General Graardor", 400));
	}

	@Test
	public void aStaleFightIsNotTaken()
	{
		FightStarts starts = new FightStarts();
		starts.onHit(FightStarts.key(GRAARDOR_ID, "General Graardor"), 100);

		assertNull(starts.take("General Graardor", 100 + FightStarts.STALE_TICKS + 1));
	}

	@Test
	public void pruningDropsFightsThatAreOver()
	{
		FightStarts starts = new FightStarts();
		starts.onHit(FightStarts.key(2, "Goblin"), 100);
		starts.onHit(FightStarts.key(GRAARDOR_ID, "General Graardor"), 350);

		starts.prune(400);

		assertNull(starts.take("Goblin", 301));
		assertEquals(Integer.valueOf(350), starts.take("General Graardor", 400));
	}
}

package com.postiepete;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class KillCountsTest
{
	private static final int NPC_MAX_AGE = 2;
	private static final int CHEST_MAX_AGE = 1000;
	private static final int WITHOUT_LOOT = 10;

	private final KillCounts killCounts = new KillCounts(NPC_MAX_AGE, CHEST_MAX_AGE, WITHOUT_LOOT);

	private static LootEvent.Kill kill(String name, int count)
	{
		return new LootEvent.Kill(name, count);
	}

	@Test
	public void readsBossKillCount()
	{
		assertEquals(kill("TzKal-Zuk", 12),
			killCounts.onMessage("Your TzKal-Zuk kill count is: <col=ff0000>12</col>.", 0));
	}

	@Test
	public void readsRaidWithItsMode()
	{
		assertEquals(kill("Theatre of Blood: Hard Mode", 40),
			killCounts.onMessage("Your completed Theatre of Blood: Hard Mode count is: <col=ff0000>40</col>.", 0));
		assertEquals(kill("Chambers of Xeric Challenge Mode", 3),
			killCounts.onMessage("Your completed Chambers of Xeric Challenge Mode count is: <col=ff0000>3</col>.", 0));
	}

	@Test
	public void readsOtherKillCountWordings()
	{
		assertEquals(kill("Wintertodt", 1234),
			killCounts.onMessage("Your subdued Wintertodt count is: <col=ff0000>1,234</col>.", 0));
		assertEquals(kill("Gauntlet", 7),
			killCounts.onMessage("Your Gauntlet completion count is: <col=ff0000>7</col>.", 0));
		assertEquals(kill("Barrows chest", 99),
			killCounts.onMessage("Your Barrows chest count is: <col=ff0000>99</col>.", 0));
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertNull(killCounts.onMessage("Your reward point tally is: 5.", 0));
		assertNull(killCounts.onMessage("Fight duration: <col=ff0000>1:23.40</col>. Personal best: 1:20.00", 0));
	}

	@Test
	public void npcLootClaimsARecentKillCountOnce()
	{
		killCounts.onMessage("Your Vorkath kill count is: <col=ff0000>500</col>.", 100);
		assertEquals(kill("Vorkath", 500), killCounts.claimForNpcLoot(100 + NPC_MAX_AGE));
		assertNull(killCounts.claimForNpcLoot(100 + NPC_MAX_AGE));
	}

	@Test
	public void npcLootDoesNotClaimAnOldKillCount()
	{
		killCounts.onMessage("Your Vorkath kill count is: <col=ff0000>500</col>.", 100);
		assertNull(killCounts.claimForNpcLoot(101 + NPC_MAX_AGE));
	}

	@Test
	public void npcLootKilledAfterAnotherActivityDoesNotTakeItsKillCount()
	{
		// A lap count from finishing a lap, then a Man killed a few seconds later
		killCounts.onMessage("Your Seers' Village Rooftop lap count is: <col=ff0000>50</col>.", 100);
		assertNull(killCounts.claimForNpcLoot(108));
	}

	@Test
	public void npcLootLeavesARaidsKillCountForTheChest()
	{
		killCounts.onMessage("Your completed Fractured Archive count is: <col=ff0000>8</col>.", 100);
		assertNull(killCounts.claimForNpcLoot(101));
		assertEquals(kill("Fractured Archive", 8), killCounts.claimForChest("Fractured Archive", 600));
	}

	@Test
	public void chestClaimsAKillCountThatNamesIt()
	{
		killCounts.onMessage("Your completed Theatre of Blood: Hard Mode count is: <col=ff0000>40</col>.", 100);
		assertEquals(kill("Theatre of Blood: Hard Mode", 40), killCounts.claimForChest("Theatre of Blood", 900));
	}

	@Test
	public void chestDoesNotClaimAnotherBosssKillCount()
	{
		killCounts.onMessage("Your Sol Heredit kill count is: <col=ff0000>2</col>.", 100);
		assertNull(killCounts.claimForChest("Fortis Colosseum", 101));
		// The Colosseum chest asks for Sol Heredit's by name, and the failed claim above left it there
		assertEquals(kill("Sol Heredit", 2), killCounts.claimForChest("Sol Heredit", 102));
	}

	@Test
	public void chestDoesNotClaimAnOldKillCount()
	{
		killCounts.onMessage("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>5</col>.", 100);
		assertNull(killCounts.claimForChest("Tombs of Amascut", 101 + CHEST_MAX_AGE));
	}

	@Test
	public void infernoWithoutLootBecomesAKillOnceItsWaitIsOver()
	{
		killCounts.onMessage("Your TzKal-Zuk kill count is: <col=ff0000>3</col>.", 100);
		assertNull(killCounts.takeKillWithoutLoot(100 + WITHOUT_LOOT));
		assertEquals(kill("TzKal-Zuk", 3), killCounts.takeKillWithoutLoot(101 + WITHOUT_LOOT));
		assertNull(killCounts.takeKillWithoutLoot(102 + WITHOUT_LOOT));
	}

	@Test
	public void killWithLootIsNotAlsoAKillWithoutLoot()
	{
		killCounts.onMessage("Your TzKal-Zuk kill count is: <col=ff0000>3</col>.", 100);
		assertEquals(kill("TzKal-Zuk", 3), killCounts.claimForNpcLoot(100));
		assertNull(killCounts.takeKillWithoutLoot(200));
	}

	@Test
	public void otherKillCountsAreNeverKillsWithoutLoot()
	{
		killCounts.onMessage("Your Vorkath kill count is: <col=ff0000>500</col>.", 100);
		assertNull(killCounts.takeKillWithoutLoot(200));
		killCounts.onMessage("Your Ardougne Rooftop lap count is: <col=ff0000>12</col>.", 300);
		assertNull(killCounts.takeKillWithoutLoot(400));
		killCounts.onMessage("Your Sol Heredit kill count is: <col=ff0000>2</col>.", 500);
		assertNull(killCounts.takeKillWithoutLoot(600));
	}

	@Test
	public void wintertodtIsAKillWithoutLoot()
	{
		killCounts.onMessage("Your subdued Wintertodt count is: <col=ff0000>1,234</col>.", 100);
		assertEquals(kill("Wintertodt", 1234), killCounts.takeKillWithoutLoot(200));
	}
}

package com.postiepete;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.regex.Matcher;
import org.junit.Test;

public class KillTimeTest
{
	@Test
	public void onlyChestsOpenedLongAfterTheirTimeTakeAnOldKillTime()
	{
		int shortWindow = PostiePetePlugin.chestKillTimeMaxAge("Barrows");
		for (String chest : new String[]{"Theatre of Blood", "Tombs of Amascut", "Chambers of Xeric", "Fractured Archive",
			"Fortis Colosseum", "Doom of Mokhaiotl"})
		{
			assertTrue(chest, PostiePetePlugin.chestKillTimeMaxAge(chest) > shortWindow);
		}
		assertEquals(shortWindow, PostiePetePlugin.chestKillTimeMaxAge("Clue Scroll (Hard)"));
		assertEquals(shortWindow, PostiePetePlugin.chestKillTimeMaxAge("Reward cart (Wintertodt)"));
		assertEquals(shortWindow, PostiePetePlugin.chestKillTimeMaxAge(null));
	}

	@Test
	public void newPersonalBestIsTheDuration()
	{
		LootEvent.KillTime time = parse("Fight duration: <col=ff0000>1:19.80</col> (new personal best)");
		assertEquals(79.8, time.getDuration(), 1e-9);
		assertEquals(79.8, time.getPersonalBest(), 1e-9);
		assertTrue(time.isNewPersonalBest());
	}

	@Test
	public void sendsThePersonalBestTheMessageShows()
	{
		LootEvent.KillTime time = parse("Fight duration: <col=ff0000>1:23.40</col>. Personal best: 1:20.00");
		assertEquals(83.4, time.getDuration(), 1e-9);
		assertEquals(80.0, time.getPersonalBest(), 1e-9);
		assertFalse(time.isNewPersonalBest());
	}

	@Test
	public void readsTheColosseumRunTime()
	{
		// As seen in game, after "Wave 12 completed!"
		LootEvent.KillTime time = parse("Colosseum duration: <col=ef1020>30:37</col> (new personal best)");
		assertEquals(1837.0, time.getDuration(), 1e-9);
		assertTrue(time.isNewPersonalBest());

		time = parse("Colosseum duration: @mes_hl_red@31:02.40</col>. Personal best: @mes_hl_red@30:37.00</col>");
		assertEquals(1862.4, time.getDuration(), 1e-9);
		assertEquals(1837.0, time.getPersonalBest(), 1e-9);
	}

	@Test
	public void aTimeThatTiesThePersonalBestIsNotANewOne()
	{
		LootEvent.KillTime time = parse("Fight duration: <col=ff0000>1:20.00</col>. Personal best: 1:20.00");
		assertEquals(80.0, time.getDuration(), 1e-9);
		assertEquals(80.0, time.getPersonalBest(), 1e-9);
		assertFalse(time.isNewPersonalBest());
	}

	@Test
	public void readsAColouredPersonalBest()
	{
		LootEvent.KillTime time = parse(
			"Theatre of Blood completion time: <col=ff0000>25:01.20</col>. Personal best: <col=ff0000>24:10.80</col>");
		assertEquals(1501.2, time.getDuration(), 1e-9);
		assertEquals(1450.8, time.getPersonalBest(), 1e-9);
	}

	@Test
	public void readsHighlightCodes()
	{
		LootEvent.KillTime time = parse("Fight duration: @mes_hl_red@0:48.60</col>. Personal best: @mes_hl_red@0:41.20");
		assertEquals(48.6, time.getDuration(), 1e-9);
		assertEquals(41.2, time.getPersonalBest(), 1e-9);
	}

	@Test
	public void noPersonalBestWhenTheMessageShowsNone()
	{
		LootEvent.KillTime time = parse("The Fractured Archive: Total completion time: <col=ef1020>18:05.80</col>");
		assertEquals(1085.8, time.getDuration(), 1e-9);
		assertNull(time.getPersonalBest());
		assertFalse(time.isNewPersonalBest());
	}

	@Test
	public void raidCompletionTimesBelongToTheirChest()
	{
		assertEquals("Theatre of Blood", PostiePetePlugin.killTimeRaid(
			"Theatre of Blood completion time: 17:29.40. Personal best: 17:22.00"));
		assertEquals("Tombs of Amascut", PostiePetePlugin.killTimeRaid(
			"Tombs of Amascut: Expert Mode challenge completion time: 25:10.20. Personal best: 24:01.80"));
		assertEquals("Fractured Archive", PostiePetePlugin.killTimeRaid(
			"The Fractured Archive: Total completion time: 18:05.80"));
		assertNull(PostiePetePlugin.killTimeRaid("Fight duration: 1:23.40. Personal best: 1:20.00"));
	}

	private static LootEvent.KillTime parse(String message)
	{
		Matcher matcher = PostiePetePlugin.KILL_DURATION_PATTERN.matcher(message);
		assertTrue(message, matcher.find());
		return PostiePetePlugin.parseKillTime(matcher);
	}
}

