import java.util.List;
import java.util.regex.Matcher;
import net.runelite.client.util.Text;
import org.junit.Test;

public class TheatreOfBloodTest
{
	@Test
	public void roomWithItsTime()
	{
		Matcher matcher = TheatreOfBlood.ROOM_COMPLETE_PATTERN.matcher(Text.removeTags(
			"Wave 'The Maiden of Sugadinti' (Normal Mode) complete!<br>Duration: <col=ff0000>2:05.40</col><br>"
				+ "Total: <col=ff0000>2:05.40</col>"));
		assertTrue(matcher.lookingAt());
		assertEquals("The Maiden of Sugadinti", matcher.group("room"));
		assertEquals("2:05.40", matcher.group("time"));
	}

	@Test
	public void verzikRoomInHardMode()
	{
		Matcher matcher = TheatreOfBlood.ROOM_COMPLETE_PATTERN.matcher(
			"Wave 'The Final Challenge' (Hard Mode) complete!Duration: 4:12Total: 24:30");
		assertTrue(matcher.lookingAt());
		assertEquals("The Final Challenge", matcher.group("room"));
		assertEquals("4:12", matcher.group("time"));
	}

	@Test
	public void colosseumWaveIsNotARoom()
	{
		assertFalse(new TheatreOfBlood().onRoomMessage("Wave 2 completed! Wave duration: 1:09.60"));
	}

	@Test
	public void theFirstRoomStartsANewRun()
	{
		TheatreOfBlood tob = new TheatreOfBlood();
		assertTrue(tob.onRoomMessage("Wave 'The Maiden of Sugadinti' (Normal Mode) complete!Duration: 2:30Total: 2:30"));
		assertTrue(tob.onRoomMessage("Wave 'The Pestilent Bloat' (Normal Mode) complete!Duration: 1:00Total: 3:30"));
		// Wiped, and started again
		tob.onRoomMessage("Wave 'The Maiden of Sugadinti' (Normal Mode) complete!Duration: 2:05.40Total: 2:05.40");
		tob.onRoomMessage("Wave 'Xarpus' (Normal Mode) complete!Duration: 3:06.60Total: 5:12");

		List<LootEvent.Split> splits = tob.consumeSplits();
		assertEquals(2, splits.size());
		assertEquals(new LootEvent.Split("The Maiden of Sugadinti", 125.4), splits.get(0));
		assertEquals(new LootEvent.Split("Xarpus", 186.6), splits.get(1));
	}

	@Test
	public void raidTimeIsTheCompletionTimeInVerziksRoomMessage()
	{
		LootEvent.KillTime time = TheatreOfBlood.completionTime(
			"Wave 'The Final Challenge' (Normal Mode) complete!<br>Duration: <col=ff0000>5:18.00</col><br>"
				+ "Theatre of Blood completion time: <col=ff0000>18:23.40</col>. Personal best: 16:00.60");
		assertEquals(1103.4, time.getDuration(), 1e-9);
		assertEquals(960.6, time.getPersonalBest(), 1e-9);
		assertFalse(time.isNewPersonalBest());
	}

	@Test
	public void raidTimeNewPersonalBest()
	{
		LootEvent.KillTime time = TheatreOfBlood.completionTime(
			"Wave 'The Final Challenge' (Hard Mode) complete!<br>Duration: <col=ff0000>5:18.00</col><br>"
				+ "Theatre of Blood: Hard Mode completion time: <col=ff0000>24:10.20</col> (new personal best)");
		assertEquals(1450.2, time.getDuration(), 1e-9);
		assertTrue(time.isNewPersonalBest());
	}

	@Test
	public void roomsBeforeVerzikHaveNoRaidTime()
	{
		assertNull(TheatreOfBlood.completionTime(
			"Wave 'Xarpus' (Normal Mode) complete!<br>Duration: <col=ff0000>3:06.60</col><br>"
				+ "Total: <col=ff0000>13:05.40</col>"));
		assertNull(TheatreOfBlood.completionTime(
			"Theatre of Blood total completion time: <col=ff0000>20:52.80</col>. Personal best: 17:53.40"));
	}
}

package com.postiepete;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import net.runelite.client.util.Text;
import org.junit.Test;

public class TombsOfAmascutTest
{
	// As RuneLite's chat commands tests have it
	private static final String WARDENS = "Challenge complete: The Wardens. Duration: <col=ef1020>9:40</col><br>"
		+ "Tombs of Amascut: Expert Mode challenge completion time: <col=ef1020>25:10.20</col>. Personal best: 24:01.80";

	@Test
	public void challengesComeInOrderAndTheWardensCompleteTheRaid()
	{
		TombsOfAmascut toa = new TombsOfAmascut();
		assertTrue(toa.onChallengeMessage(challenge("Path of Het", "2:10.20", "2:10.20"), 300));
		assertTrue(toa.onChallengeMessage(challenge("Akkha", "1:47.40", "3:57.60"), 300));
		assertTrue(toa.onChallengeMessage(challenge("Path of Scabaras", "2:00", "5:57.60"), 300));
		assertTrue(toa.onChallengeMessage(Text.removeTags(WARDENS), 300));
		// A new raid can't start before the chest is opened: later messages don't change the completed one
		assertEquals(Integer.valueOf(300), toa.consumeInvocation());
		assertNull(toa.consumeInvocation());

		List<LootEvent.Split> splits = toa.consumeSplits();
		assertEquals(4, splits.size());
		assertEquals(new LootEvent.Split("Path of Het", 130.2), splits.get(0));
		assertEquals(new LootEvent.Split("Akkha", 107.4), splits.get(1));
		assertEquals(new LootEvent.Split("Path of Scabaras", 120.0), splits.get(2));
		assertEquals(new LootEvent.Split("The Wardens", 580.0), splits.get(3));
	}

	@Test
	public void theFirstChallengeOfARaidClearsAFailedOne()
	{
		TombsOfAmascut toa = new TombsOfAmascut();
		toa.onChallengeMessage(challenge("Path of Apmeken", "2:35", "2:35"), 150);
		toa.onChallengeMessage(challenge("Ba-Ba", "1:30", "4:05"), 150);
		// Wiped, and started again: its total is its own time
		toa.onChallengeMessage(challenge("Path of Crondis", "1:50.40", "1:50.40"), 150);

		List<LootEvent.Split> splits = toa.consumeSplits();
		assertEquals(1, splits.size());
		assertEquals("Path of Crondis", splits.get(0).getName());
	}

	@Test
	public void personalPointsWithoutATotal()
	{
		TombsOfAmascut toa = new TombsOfAmascut();
		assertNull(toa.consumePoints());

		toa.onChallengeMessage(challenge("Path of Het", "2:10.20", "2:10.20"), 300);
		toa.onPersonalPoints(18450);
		assertEquals(new LootEvent.Points(null, 18450), toa.consumePoints());
		assertNull(toa.consumePoints());

		// A raid's points don't carry over to the next one
		toa.onPersonalPoints(9000);
		toa.onChallengeMessage(challenge("Path of Crondis", "1:50.40", "1:50.40"), 300);
		assertNull(toa.consumePoints());
	}

	@Test
	public void raidTimeIsTheCompletionTimeInTheWardensMessage()
	{
		LootEvent.KillTime time = TombsOfAmascut.completionTime(WARDENS);
		assertEquals(1510.2, time.getDuration(), 1e-9);
		assertEquals(1441.8, time.getPersonalBest(), 1e-9);
		assertFalse(time.isNewPersonalBest());

		time = TombsOfAmascut.completionTime("Challenge complete: The Wardens. Duration: <col=ef1020>8:30</col><br>"
			+ "Tombs of Amascut challenge completion time: <col=ef1020>8:31</col> (new personal best)");
		assertEquals(511.0, time.getDuration(), 1e-9);
		assertTrue(time.isNewPersonalBest());

		assertNull(TombsOfAmascut.completionTime(
			"Tombs of Amascut total completion time: <col=ef1020>27:01</col> (new personal best)"));
		assertNull(TombsOfAmascut.completionTime(challenge("Akkha", "1:47.40", "3:57.60")));
	}

	@Test
	public void fracturedArchiveBossesAreNotChallenges()
	{
		TombsOfAmascut toa = new TombsOfAmascut();
		assertFalse(toa.onChallengeMessage(Text.removeTags(
			"Challenge complete: Ocellus. Duration: <col=ef1020>2:25.80</col>. Total: <col=ef1020>2:25.80</col>"
				+ " (new personal best)"), 0));
		assertFalse(toa.onChallengeMessage("Challenge started: Archive Guardian.", 0));
		assertTrue(toa.consumeSplits().isEmpty());
	}

	private static String challenge(String room, String duration, String total)
	{
		return Text.removeTags("Challenge complete: " + room + ". Duration: <col=ef1020>" + duration + "</col>. Total: "
			+ "<col=ef1020>" + total + "</col>");
	}
}

package com.postiepete;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import java.util.Collections;
import org.junit.Test;

public class TripGearTest
{
	private static PlayerItems items(int weaponId)
	{
		return new PlayerItems(
			Collections.singletonMap("WEAPON", new PlayerItems.SlotItem(weaponId, 1)),
			Collections.emptyMap(), null, null);
	}

	@Test
	public void keepsTheFirstHitsItemsForTheWholeTrip()
	{
		TripGear trip = new TripGear();
		PlayerItems start = items(20997);
		trip.onHit(100, () -> start);
		trip.onHit(500, () -> items(4151));

		assertSame(start, trip.get(600));
	}

	@Test
	public void noTripBeforeTheFirstHit()
	{
		assertNull(new TripGear().get(100));
	}

	@Test
	public void bankingStartsANewTrip()
	{
		TripGear trip = new TripGear();
		trip.onHit(100, () -> items(20997));
		trip.end();

		assertNull(trip.get(110));
		PlayerItems next = items(4151);
		trip.onHit(200, () -> next);
		assertSame(next, trip.get(210));
	}

	@Test
	public void aLongBreakStartsANewTrip()
	{
		TripGear trip = new TripGear();
		trip.onHit(100, () -> items(20997));

		assertNull(trip.get(101 + TripGear.IDLE_TICKS));
		PlayerItems next = items(4151);
		trip.onHit(101 + TripGear.IDLE_TICKS, () -> next);
		assertSame(next, trip.get(200 + TripGear.IDLE_TICKS));
	}
}

